class Sensor : public Napi::ObjectWrap<Sensor> {
 public:
  Sensor(const Napi::CallbackInfo& info) : Napi::ObjectWrap<Sensor>(info) {
    handle_ = sensor_open(info[0].As<Napi::String>().Utf8Value().c_str());
  }
  ~Sensor() { sensor_close(handle_); }   // the addon owns the native handle
  Napi::Value Read(const Napi::CallbackInfo& info);
 private:
  sensor_t* handle_;
};
